export type TranslationKey = keyof (typeof messages)["uz"];
type TranslationValues = Record<string, string | number>;

export const MEDIA_ERROR_TRANSLATION_KEYS = {
  insecure_context: "scan.media.insecure_context",
  unsupported: "scan.media.unsupported",
  permission_denied: "scan.media.permission_denied",
  device_missing: "scan.media.device_missing",
  device_busy: "scan.media.device_busy",
  constraints_unavailable: "scan.media.constraints_unavailable",
  unknown: "scan.media.unknown",
} as const satisfies Record<string, TranslationKey>;

function format(message: string, values?: TranslationValues) {
  return values
    ? message.replace(/\{(\w+)\}/g, (_, key: string) => String(values[key] ?? `{${key}}`))
    : message;
}

export function translate(
  language: AppLanguage,
  key: TranslationKey,
  values?: TranslationValues
) {
  return format(messages[language][key], values);
}

interface LanguageContextValue {
  language: AppLanguage;
  setLanguage: (language: AppLanguage) => void;
  t: (key: TranslationKey, values?: TranslationValues) => string;
}

const LanguageContext = createContext<LanguageContextValue | null>(null);

export function LanguageProvider({ children }: { children: ReactNode }) {
  const [language, setLanguageState] = useState<AppLanguage>("uz");

  useEffect(() => {
    const stored = window.localStorage.getItem(STORAGE_KEY);
    if (stored !== "uz" && stored !== "ru") return;
    const timer = window.setTimeout(() => setLanguageState(stored), 0);
    return () => window.clearTimeout(timer);
  }, []);

  const setLanguage = useCallback((nextLanguage: AppLanguage) => {
    setLanguageState(nextLanguage);
    window.localStorage.setItem(STORAGE_KEY, nextLanguage);
  }, []);

  useEffect(() => {
    document.documentElement.lang = language;
  }, [language]);

  const value = useMemo<LanguageContextValue>(
    () => ({ language, setLanguage, t: (key, values) => translate(language, key, values) }),
    [language, setLanguage]
  );

  return <LanguageContext.Provider value={value}>{children}</LanguageContext.Provider>;
}

export function useLanguage() {
  const value = useContext(LanguageContext);
  if (!value) throw new Error("useLanguage must be used inside LanguageProvider");
  return value;
}
